INSERT INTO modules (id, unit_id, order_index, slug, title, description, is_published) VALUES
('00000001-0000-0000-0000-000000000005', '00000000-0000-0000-0001-000000000001', 5, 'colores-adjetivos', '{"en": "Colors and Basic Adjectives", "es": "Colores y Adjetivos Básicos"}', '{"en": "Learn to describe the world around you using colors and basic adjectives.", "es": "Aprende a describir el mundo que te rodea usando colores y adjetivos básicos."}', true),
('00000001-0000-0000-0000-000000000006', '00000000-0000-0000-0001-000000000001', 6, 'la-familia', '{"en": "The Family", "es": "La Familia"}', '{"en": "Learn to talk about your family members in English.", "es": "Aprende a hablar sobre los miembros de tu familia en inglés."}', true),
('00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 7, 'comida-bebida', '{"en": "Food and Drink", "es": "Comida y Bebida"}', '{"en": "Discover how to talk about food, drinks, and dining out in English.", "es": "Descubre cómo hablar sobre comida, bebidas y comer fuera en inglés."}', true),
('00000001-0000-0000-0000-000000000008', '00000000-0000-0000-0001-000000000001', 8, 'cuerpo-humano', '{"en": "The Human Body", "es": "El Cuerpo Humano"}', '{"en": "Learn the parts of the body and how to talk about health in English.", "es": "Aprende las partes del cuerpo y cómo hablar de salud en inglés."}', true);

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0005-000000000001', '00000001-0000-0000-0000-000000000005', '00000000-0000-0000-0001-000000000001', 1, 'los-colores', '{"en": "Colors", "es": "Los Colores"}', '{"en": "Learn the basic colors in English.", "es": "Aprende los colores básicos en inglés."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás los colores más importantes en inglés. Los colores son palabras esenciales que usamos todos los días para describir objetos, ropa, naturaleza y mucho más. Dominar los colores te permitirá comunicarte de manera más precisa y expresiva.", "sections": [{"type": "explanation", "title": "LOS COLORES EN INGLÉS", "text": "En inglés, los colores funcionan como adjetivos y generalmente se colocan antes del sustantivo que modifican. Por ejemplo: ''a red apple'' (una manzana roja). A diferencia del español, los adjetivos no cambian de género ni número: se dice ''a red car'' y ''two red cars'' sin modificar el color."}, {"type": "table", "title": "COLORES BÁSICOS", "headers": ["English", "Español", "Ejemplo"], "rows": [["red", "rojo/a", "a red apple"], ["blue", "azul", "a blue sky"], ["green", "verde", "green grass"], ["yellow", "amarillo/a", "a yellow sun"], ["orange", "naranja", "an orange cat"], ["purple", "morado/a", "a purple flower"], ["pink", "rosa", "a pink dress"], ["white", "blanco/a", "white snow"], ["black", "negro/a", "a black car"], ["gray", "gris", "a gray cloud"], ["brown", "marrón/café", "brown eyes"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "My car is red.", "es": "Mi carro es rojo."}, {"en": "She has blue eyes.", "es": "Ella tiene ojos azules."}, {"en": "I like green apples.", "es": "Me gustan las manzanas verdes."}, {"en": "He is wearing a black shirt.", "es": "Él lleva puesta una camisa negra."}]}, {"type": "note", "variant": "tip", "text": "Recuerda que en inglés el adjetivo va ANTES del sustantivo: ''a blue car'' (no ''a car blue''). Esta es una diferencia importante con el español donde el adjetivo puede ir después."}]}', true),
('00000002-0000-0000-0005-000000000002', '00000001-0000-0000-0000-000000000005', '00000000-0000-0000-0001-000000000001', 2, 'tamano-forma', '{"en": "Size and Shape", "es": "Tamaño y Forma"}', '{"en": "Learn adjectives for size and shape.", "es": "Aprende adjetivos de tamaño y forma."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás adjetivos para describir el tamaño y la forma de los objetos en inglés. Estos adjetivos son muy útiles en la vida cotidiana, ya sea para describir una habitación, una persona o cualquier objeto que te rodea.", "sections": [{"type": "explanation", "title": "ADJETIVOS DE TAMAÑO Y FORMA", "text": "Los adjetivos de tamaño y forma en inglés también se colocan antes del sustantivo. Algunos vienen en pares opuestos (antónimos): big/small, tall/short, long/short. Nota que ''short'' puede significar tanto ''bajo/a'' (para personas) como ''corto/a'' (para objetos), dependiendo del contexto."}, {"type": "table", "title": "TAMAÑO Y FORMA", "headers": ["English", "Español", "Ejemplo"], "rows": [["big / large", "grande", "a big house"], ["small / little", "pequeño/a", "a small dog"], ["tall", "alto/a", "a tall building"], ["short", "bajo/a / corto/a", "a short person"], ["long", "largo/a", "a long road"], ["round", "redondo/a", "a round table"], ["square", "cuadrado/a", "a square box"], ["thin / slim", "delgado/a", "a thin book"], ["fat / thick", "gordo/a / grueso/a", "a fat cat"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "That is a big elephant.", "es": "Ese es un elefante grande."}, {"en": "She has long hair.", "es": "Ella tiene el cabello largo."}, {"en": "I live in a small apartment.", "es": "Vivo en un apartamento pequeño."}, {"en": "The table is round.", "es": "La mesa es redonda."}]}, {"type": "note", "variant": "warning", "text": "Ten cuidado con ''short'': puede significar ''bajo'' cuando describes a una persona (''He is short'') o ''corto'' cuando describes un objeto (''a short pencil''). El contexto determina el significado."}]}', true),
('00000002-0000-0000-0005-000000000003', '00000001-0000-0000-0000-000000000005', '00000000-0000-0000-0001-000000000001', 3, 'adjetivos-calidad', '{"en": "Quality Adjectives", "es": "Adjetivos de Calidad"}', '{"en": "Learn adjectives that describe qualities.", "es": "Aprende adjetivos que describen cualidades."}', 'grammar', 35, 15, '{"intro": "En esta lección aprenderás adjetivos que describen cualidades y características de personas, lugares y cosas. Estos adjetivos opuestos son muy comunes en inglés y te ayudarán a expresar opiniones y hacer comparaciones básicas.", "sections": [{"type": "explanation", "title": "ADJETIVOS OPUESTOS (ANTÓNIMOS)", "text": "Muchos adjetivos en inglés vienen en pares de palabras con significados opuestos. Aprender los antónimos juntos es una excelente estrategia para duplicar tu vocabulario más rápido. Para negar un adjetivo en inglés usamos ''not'': ''It is not good'' (No es bueno)."}, {"type": "table", "title": "ADJETIVOS DE CALIDAD", "headers": ["English", "Opuesto", "Español"], "rows": [["good", "bad", "bueno / malo"], ["new", "old", "nuevo / viejo"], ["hot", "cold", "caliente / frío"], ["fast", "slow", "rápido / lento"], ["easy", "difficult / hard", "fácil / difícil"], ["clean", "dirty", "limpio / sucio"], ["right", "wrong", "correcto / incorrecto"], ["cheap", "expensive", "barato / caro"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "This coffee is hot.", "es": "Este café está caliente."}, {"en": "English is not difficult.", "es": "El inglés no es difícil."}, {"en": "My phone is new.", "es": "Mi teléfono es nuevo."}, {"en": "The street is clean.", "es": "La calle está limpia."}]}, {"type": "note", "variant": "tip", "text": "Para aprender vocabulario más rápido, estudia los antónimos en pares: good/bad, hot/cold, fast/slow. Cuando aprendes una palabra, intenta recordar también su opuesto."}]}', true),
('00000002-0000-0000-0005-000000000004', '00000001-0000-0000-0000-000000000005', '00000000-0000-0000-0001-000000000001', 4, 'describir-personas', '{"en": "Describing People", "es": "Describir Personas"}', '{"en": "Learn to describe people in English.", "es": "Aprende a describir personas en inglés."}', 'grammar', 40, 15, '{"intro": "En esta lección aprenderás a describir personas usando adjetivos en inglés. Podrás hablar sobre la apariencia física y la personalidad de las personas, lo cual es muy útil para presentar a alguien o hablar sobre personas que conoces.", "sections": [{"type": "explanation", "title": "DESCRIBIR LA APARIENCIA FÍSICA", "text": "Para describir la apariencia de una persona usamos el verbo ''to be'' (ser/estar) o ''to have'' (tener). Usamos ''to be'' para características generales como la altura o el carácter: ''She is tall'' (Ella es alta). Usamos ''to have'' para características como el color de ojos o cabello: ''He has brown eyes'' (Él tiene ojos cafés)."}, {"type": "table", "title": "ADJETIVOS PARA DESCRIBIR PERSONAS", "headers": ["English", "Español", "Ejemplo"], "rows": [["tall", "alto/a", "He is tall."], ["short", "bajo/a", "She is short."], ["young", "joven", "He is young."], ["old", "viejo/a / mayor", "She is old."], ["pretty / beautiful", "bonita / hermosa", "She is pretty."], ["handsome", "guapo", "He is handsome."], ["friendly", "amigable / simpático", "She is friendly."], ["serious", "serio/a", "He is serious."], ["funny", "chistoso/a", "She is funny."]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "Apariencia", "en": "My friend is tall and handsome.", "es": "Mi amigo es alto y guapo."}, {"label": "Personalidad", "en": "She is very friendly and funny.", "es": "Ella es muy amigable y chistosa."}, {"label": "Con ''have''", "en": "He has short black hair.", "es": "Él tiene el cabello negro y corto."}, {"label": "Negativo", "en": "She is not serious, she is funny.", "es": "Ella no es seria, es chistosa."}]}, {"type": "note", "variant": "info", "text": "''Pretty'' se usa principalmente para mujeres, mientras que ''handsome'' se usa para hombres. Para ambos géneros puedes usar ''attractive'' o ''good-looking''."}]}', true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0005-0001-0001-000000000001', '00000002-0000-0000-0005-000000000001', 1, 'flashcard', '{"text": "red", "subtext": "color"}', '{"text": "rojo", "phonetic": "/rɛd/"}', null, null),
('00000003-0005-0001-0002-000000000001', '00000002-0000-0000-0005-000000000001', 2, 'flashcard', '{"text": "blue", "subtext": "color"}', '{"text": "azul", "phonetic": "/bluː/"}', null, null),
('00000003-0005-0001-0003-000000000001', '00000002-0000-0000-0005-000000000001', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''verde'' en inglés?"}', '{"text": "green"}', '["red", "gray", "brown"]', '{"es": "''Green'' significa verde en inglés. Se pronuncia /ɡriːn/."}'),
('00000003-0005-0001-0004-000000000001', '00000002-0000-0000-0005-000000000001', 4, 'multiple_choice', '{"text": "What color is the sky on a clear day?"}', '{"text": "blue"}', '["red", "green", "yellow"]', '{"es": "El cielo en un día despejado es azul (blue)."}'),
('00000003-0005-0001-0005-000000000001', '00000002-0000-0000-0005-000000000001', 5, 'fill_blank', '{"text": "The sun is ___ ."}', '{"text": "yellow", "accepted": ["yellow"]}', null, '{"es": "El sol es amarillo. En inglés usamos ''yellow'' para describir el color del sol."}'),
('00000003-0005-0001-0006-000000000001', '00000002-0000-0000-0005-000000000001', 6, 'fill_blank', '{"text": "Snow is ___ ."}', '{"text": "white", "accepted": ["white"]}', null, '{"es": "La nieve es blanca. En inglés ''white'' significa blanco."}'),
('00000003-0005-0001-0007-000000000001', '00000002-0000-0000-0005-000000000001', 7, 'translation', '{"text": "Mi gato es negro."}', '{"text": "My cat is black.", "accepted": ["My cat is black."]}', null, '{"es": "''Black'' significa negro. La estructura es: sujeto + verbo to be + adjetivo de color."}'),
('00000003-0005-0001-0008-000000000001', '00000002-0000-0000-0005-000000000001', 8, 'translation', '{"text": "Ella tiene los ojos cafés."}', '{"text": "She has brown eyes.", "accepted": ["She has brown eyes."]}', null, '{"es": "Usamos ''to have'' para describir características como el color de ojos. ''Brown'' significa marrón o café."}'),

('00000003-0005-0002-0001-000000000001', '00000002-0000-0000-0005-000000000002', 1, 'flashcard', '{"text": "big", "subtext": "size adjective"}', '{"text": "grande", "phonetic": "/bɪɡ/"}', null, null),
('00000003-0005-0002-0002-000000000001', '00000002-0000-0000-0005-000000000002', 2, 'flashcard', '{"text": "tall", "subtext": "height adjective"}', '{"text": "alto/a", "phonetic": "/tɔːl/"}', null, null),
('00000003-0005-0002-0003-000000000001', '00000002-0000-0000-0005-000000000002', 3, 'multiple_choice', '{"text": "¿Cuál es el opuesto de ''big'' en inglés?"}', '{"text": "small"}', '["tall", "round", "long"]', '{"es": "El opuesto de ''big'' (grande) es ''small'' (pequeño)."}'),
('00000003-0005-0002-0004-000000000001', '00000002-0000-0000-0005-000000000002', 4, 'multiple_choice', '{"text": "What shape is a pizza?"}', '{"text": "round"}', '["square", "long", "thin"]', '{"es": "Una pizza es redonda. En inglés ''round'' significa redondo."}'),
('00000003-0005-0002-0005-000000000001', '00000002-0000-0000-0005-000000000002', 5, 'fill_blank', '{"text": "An elephant is very ___ ."}', '{"text": "big", "accepted": ["big", "large"]}', null, '{"es": "Un elefante es muy grande. Podemos usar ''big'' o ''large'' para decir grande."}'),
('00000003-0005-0002-0006-000000000001', '00000002-0000-0000-0005-000000000002', 6, 'fill_blank', '{"text": "She has ___ hair. (cabello largo)"}', '{"text": "long", "accepted": ["long"]}', null, '{"es": "''Long'' significa largo. Se usa para describir el cabello, una carretera, un río, etc."}'),
('00000003-0005-0002-0007-000000000001', '00000002-0000-0000-0005-000000000002', 7, 'translation', '{"text": "La mesa es cuadrada."}', '{"text": "The table is square.", "accepted": ["The table is square."]}', null, '{"es": "''Square'' significa cuadrado. La estructura es: sujeto + verbo to be + adjetivo."}'),
('00000003-0005-0002-0008-000000000001', '00000002-0000-0000-0005-000000000002', 8, 'translation', '{"text": "Vivo en una casa pequeña."}', '{"text": "I live in a small house.", "accepted": ["I live in a small house.", "I live in a little house."]}', null, '{"es": "''Small'' y ''little'' ambos significan pequeño. El adjetivo va antes del sustantivo en inglés."}'),

('00000003-0005-0003-0001-000000000001', '00000002-0000-0000-0005-000000000003', 1, 'flashcard', '{"text": "good", "subtext": "quality adjective"}', '{"text": "bueno", "phonetic": "/ɡʊd/"}', null, null),
('00000003-0005-0003-0002-000000000001', '00000002-0000-0000-0005-000000000003', 2, 'flashcard', '{"text": "difficult", "subtext": "quality adjective"}', '{"text": "difícil", "phonetic": "/ˈdɪfɪkəlt/"}', null, null),
('00000003-0005-0003-0003-000000000001', '00000002-0000-0000-0005-000000000003', 3, 'multiple_choice', '{"text": "¿Cuál es el opuesto de ''hot'' en inglés?"}', '{"text": "cold"}', '["fast", "slow", "bad"]', '{"es": "El opuesto de ''hot'' (caliente) es ''cold'' (frío)."}'),
('00000003-0005-0003-0004-000000000001', '00000002-0000-0000-0005-000000000003', 4, 'multiple_choice', '{"text": "Which adjective means ''rápido''?"}', '{"text": "fast"}', '["slow", "clean", "new"]', '{"es": "''Fast'' significa rápido. Su opuesto es ''slow'' (lento)."}'),
('00000003-0005-0003-0005-000000000001', '00000002-0000-0000-0005-000000000003', 5, 'fill_blank', '{"text": "This exercise is ___ . (fácil)"}', '{"text": "easy", "accepted": ["easy"]}', null, '{"es": "''Easy'' significa fácil. Su opuesto es ''difficult'' o ''hard''."}'),
('00000003-0005-0003-0006-000000000001', '00000002-0000-0000-0005-000000000003', 6, 'fill_blank', '{"text": "My room is very ___ . (limpio)"}', '{"text": "clean", "accepted": ["clean"]}', null, '{"es": "''Clean'' significa limpio. Su opuesto es ''dirty'' (sucio)."}'),
('00000003-0005-0003-0007-000000000001', '00000002-0000-0000-0005-000000000003', 7, 'translation', '{"text": "El café está caliente."}', '{"text": "The coffee is hot.", "accepted": ["The coffee is hot."]}', null, '{"es": "''Hot'' significa caliente. Usamos el verbo ''to be'' para describir temperaturas."}'),
('00000003-0005-0003-0008-000000000001', '00000002-0000-0000-0005-000000000003', 8, 'translation', '{"text": "Ese carro es nuevo y rápido."}', '{"text": "That car is new and fast.", "accepted": ["That car is new and fast."]}', null, '{"es": "Podemos combinar varios adjetivos con ''and''. ''New'' significa nuevo y ''fast'' significa rápido."}'),

('00000003-0005-0004-0001-000000000001', '00000002-0000-0000-0005-000000000004', 1, 'flashcard', '{"text": "friendly", "subtext": "personality adjective"}', '{"text": "amigable / simpático", "phonetic": "/ˈfrɛndli/"}', null, null),
('00000003-0005-0004-0002-000000000001', '00000002-0000-0000-0005-000000000004', 2, 'flashcard', '{"text": "handsome", "subtext": "appearance adjective (for men)"}', '{"text": "guapo", "phonetic": "/ˈhænsəm/"}', null, null),
('00000003-0005-0004-0003-000000000001', '00000002-0000-0000-0005-000000000004', 3, 'multiple_choice', '{"text": "¿Qué adjetivo usamos para describir a una mujer bonita?"}', '{"text": "pretty"}', '["handsome", "tall", "young"]', '{"es": "''Pretty'' se usa para describir a una mujer bonita. ''Handsome'' se usa generalmente para los hombres."}'),
('00000003-0005-0004-0004-000000000001', '00000002-0000-0000-0005-000000000004', 4, 'multiple_choice', '{"text": "My teacher is very ___. She always smiles. (simpática)"}', '{"text": "friendly"}', '["serious", "old", "short"]', '{"es": "''Friendly'' significa simpático o amigable. Alguien que siempre sonríe es una persona amigable."}'),
('00000003-0005-0004-0005-000000000001', '00000002-0000-0000-0005-000000000004', 5, 'fill_blank', '{"text": "My grandfather is ___. He is 75 years old. (mayor/viejo)"}', '{"text": "old", "accepted": ["old"]}', null, '{"es": "''Old'' puede significar viejo o mayor. Se usa tanto para objetos como para personas."}'),
('00000003-0005-0004-0006-000000000001', '00000002-0000-0000-0005-000000000004', 6, 'fill_blank', '{"text": "He is ___ . He is 6 feet tall. (alto)"}', '{"text": "tall", "accepted": ["tall"]}', null, '{"es": "''Tall'' significa alto/a y se usa para describir la estatura de las personas o la altura de los edificios."}'),
('00000003-0005-0004-0007-000000000001', '00000002-0000-0000-0005-000000000004', 7, 'translation', '{"text": "Mi amigo es alto y simpático."}', '{"text": "My friend is tall and friendly.", "accepted": ["My friend is tall and friendly."]}', null, '{"es": "''Tall'' es alto y ''friendly'' es simpático. Conectamos los adjetivos con ''and''."}'),
('00000003-0005-0004-0008-000000000001', '00000002-0000-0000-0005-000000000004', 8, 'translation', '{"text": "Ella es joven y muy bonita."}', '{"text": "She is young and very pretty.", "accepted": ["She is young and very pretty.", "She is young and very beautiful."]}', null, '{"es": "''Young'' es joven y ''pretty'' es bonita. También puedes usar ''beautiful'' para bonita."}');

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0006-000000000001', '00000001-0000-0000-0000-000000000006', '00000000-0000-0000-0001-000000000001', 1, 'miembros-familia', '{"en": "Family Members", "es": "Miembros de la Familia"}', '{"en": "Learn the names of family members in English.", "es": "Aprende los nombres de los miembros de la familia en inglés."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás los nombres de los miembros de la familia en inglés. El vocabulario familiar es esencial para hablar sobre tu vida personal y para comprender conversaciones cotidianas. Aprenderás tanto los términos directos como los de la familia extendida.", "sections": [{"type": "explanation", "title": "LA FAMILIA EN INGLÉS", "text": "En inglés, los sustantivos que se refieren a personas tienen género neutro en muchos casos, pero los miembros de la familia sí tienen género: ''father'' (padre) vs. ''mother'' (madre), ''brother'' (hermano) vs. ''sister'' (hermana). Para referirte a un miembro de la familia sin especificar género puedes usar ''sibling'' (hermano/a en general) o ''parent'' (padre/madre en general)."}, {"type": "table", "title": "MIEMBROS DE LA FAMILIA", "headers": ["English", "Español", "Ejemplo"], "rows": [["father / dad", "padre / papá", "My father is 50."], ["mother / mom", "madre / mamá", "My mom is a teacher."], ["brother", "hermano", "I have one brother."], ["sister", "hermana", "My sister is 10."], ["grandfather / grandpa", "abuelo", "My grandpa is funny."], ["grandmother / grandma", "abuela", "I love my grandma."], ["uncle", "tío", "My uncle lives in Miami."], ["aunt", "tía", "My aunt has a dog."], ["cousin", "primo/a", "I have five cousins."], ["son", "hijo", "He has two sons."], ["daughter", "hija", "She is my daughter."]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I have one brother and two sisters.", "es": "Tengo un hermano y dos hermanas."}, {"en": "My grandmother is 80 years old.", "es": "Mi abuela tiene 80 años."}, {"en": "Her uncle lives in New York.", "es": "Su tío vive en Nueva York."}]}, {"type": "note", "variant": "tip", "text": "''Dad'' y ''mom'' son formas informales y cariñosas de ''father'' y ''mother''. En la conversación diaria, la mayoría de personas usan ''dad'' y ''mom''."}]}', true),
('00000002-0000-0000-0006-000000000002', '00000001-0000-0000-0000-000000000006', '00000000-0000-0000-0001-000000000001', 2, 'hablar-familia', '{"en": "Talking About Your Family", "es": "Hablar de Tu Familia"}', '{"en": "Learn to talk about your family in English.", "es": "Aprende a hablar sobre tu familia en inglés."}', 'grammar', 35, 15, '{"intro": "En esta lección aprenderás a hablar sobre tu familia en inglés usando oraciones completas. Aprenderás a decir cuántos hermanos tienes, la edad de tus familiares y cómo expresar que no tienes hermanos o familiares cercanos.", "sections": [{"type": "explanation", "title": "HABLAR DE LA FAMILIA", "text": "Para hablar de tu familia usamos principalmente el verbo ''to have'' (tener) y el verbo ''to be'' (ser/estar). Con ''to have'' expresamos posesión: ''I have a brother'' (Tengo un hermano). Para decir la edad usamos ''to be'': ''My sister is 10 years old'' (Mi hermana tiene 10 años). Para decir que no tienes algo, usamos ''don''t have'': ''I don''t have any siblings'' (No tengo hermanos)."}, {"type": "table", "title": "ESTRUCTURAS CLAVE", "headers": ["Estructura", "Ejemplo", "Español"], "rows": [["I have a/an + familiar", "I have a sister.", "Tengo una hermana."], ["I have + número + familiares", "I have two brothers.", "Tengo dos hermanos."], ["I don''t have any + familiares", "I don''t have any cousins.", "No tengo primos."], ["My + familiar + is + edad", "My dad is 45 years old.", "Mi papá tiene 45 años."], ["My + familiar + is + adjetivo", "My sister is young.", "Mi hermana es joven."]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I have a brother. He is 15 years old.", "es": "Tengo un hermano. Él tiene 15 años."}, {"en": "I don''t have any siblings. I am an only child.", "es": "No tengo hermanos. Soy hijo único."}, {"en": "My grandmother is 75 years old and very active.", "es": "Mi abuela tiene 75 años y es muy activa."}]}, {"type": "note", "variant": "info", "text": "''Siblings'' es una palabra que en inglés significa hermanos en general (sin especificar género). ''I don''t have any siblings'' equivale a decir que eres hijo único. ''Only child'' significa hijo/hija único/a."}]}', true),
('00000002-0000-0000-0006-000000000003', '00000001-0000-0000-0000-000000000006', '00000000-0000-0000-0001-000000000001', 3, 'posesivos-familia', '{"en": "Possessives with Family", "es": "Los Posesivos con Familia"}', '{"en": "Learn possessive adjectives and the apostrophe-s with family.", "es": "Aprende los adjetivos posesivos y el apóstrofo-s con la familia."}', 'grammar', 35, 15, '{"intro": "En esta lección aprenderás los adjetivos posesivos en inglés y cómo usar el apóstrofe-s para expresar posesión. Estos son dos formas diferentes de indicar a quién pertenece algo, y ambas son muy comunes en inglés cotidiano.", "sections": [{"type": "explanation", "title": "ADJETIVOS POSESIVOS", "text": "Los adjetivos posesivos en inglés van siempre antes del sustantivo y NO cambian según el género o número del objeto poseído. Solo cambian según el poseedor: my (mi/mis), your (tu/tus), his (su de él), her (su de ella), our (nuestro/a), their (su de ellos)."}, {"type": "table", "title": "ADJETIVOS POSESIVOS", "headers": ["Pronombre", "Posesivo", "Ejemplo"], "rows": [["I", "my", "my father"], ["you", "your", "your mother"], ["he", "his", "his brother"], ["she", "her", "her sister"], ["we", "our", "our grandmother"], ["they", "their", "their uncle"]]}, {"type": "explanation", "title": "EL APÓSTROFO-S (''S)", "text": "La otra forma de expresar posesión en inglés es agregar apóstrofo-s (''s) al nombre del poseedor: ''my father''s name'' significa ''el nombre de mi padre''. Esta construcción es muy natural en inglés y se usa constantemente. Nota que la estructura es opuesta al español: en inglés primero va el poseedor y después el objeto poseído."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "Posesivos", "en": "My mother''s name is María.", "es": "El nombre de mi madre es María."}, {"label": "Posesivos", "en": "His sister''s husband is a doctor.", "es": "El esposo de su hermana es médico."}, {"label": "Adjetivos posesivos", "en": "Our house is big. Their car is red.", "es": "Nuestra casa es grande. Su carro es rojo."}]}, {"type": "note", "variant": "warning", "text": "No confundas ''her'' (posesivo de ella) con ''his'' (posesivo de él). ''Her sister'' = la hermana de ella. ''His sister'' = la hermana de él. El posesivo depende del POSEEDOR, no del objeto."}]}', true),
('00000002-0000-0000-0006-000000000004', '00000001-0000-0000-0000-000000000006', '00000000-0000-0000-0001-000000000001', 4, 'describir-familiares', '{"en": "Describing Family Members", "es": "Describir a Familiares"}', '{"en": "Learn to describe your family members in detail.", "es": "Aprende a describir a tus familiares en detalle."}', 'grammar', 40, 18, '{"intro": "En esta lección aprenderás a describir a tus familiares de manera más completa, combinando información sobre su profesión, edad y apariencia. Podrás construir pequeños párrafos descriptivos sobre las personas más importantes de tu vida.", "sections": [{"type": "explanation", "title": "DESCRIBIR A UNA PERSONA", "text": "Para describir a un familiar de manera completa, podemos combinar varios tipos de información: profesión (''She is a teacher''), edad (''She is 45 years old''), apariencia (''She has brown eyes''), y personalidad (''She is very kind''). Usamos ''She'' o ''He'' para referirnos a la persona sin repetir su nombre."}, {"type": "table", "title": "VOCABULARIO PARA DESCRIBIR", "headers": ["Categoría", "Inglés", "Español"], "rows": [["Profesión", "teacher / doctor / engineer", "maestra / doctora / ingeniero"], ["Edad", "years old", "años de edad"], ["Cabello", "black / brown / blond hair", "cabello negro / café / rubio"], ["Ojos", "brown / blue / green eyes", "ojos cafés / azules / verdes"], ["Personalidad", "kind / funny / serious", "amable / chistoso / serio"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "Descripción completa", "en": "My mom is a teacher. She is 45 years old. She has brown eyes and black hair. She is very kind and funny.", "es": "Mi mamá es maestra. Tiene 45 años. Tiene ojos cafés y cabello negro. Es muy amable y chistosa."}, {"label": "Descripción corta", "en": "My brother is 20 years old. He is tall and handsome.", "es": "Mi hermano tiene 20 años. Es alto y guapo."}]}, {"type": "note", "variant": "tip", "text": "Cuando describes a alguien, empieza con su nombre o relación contigo, luego di su profesión o rol, después la edad, y finalmente la apariencia y personalidad. Esto hace que tu descripción suene natural y organizada."}]}', true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0006-0001-0001-000000000001', '00000002-0000-0000-0006-000000000001', 1, 'flashcard', '{"text": "father", "subtext": "family member"}', '{"text": "padre", "phonetic": "/ˈfɑːðər/"}', null, null),
('00000003-0006-0001-0002-000000000001', '00000002-0000-0000-0006-000000000001', 2, 'flashcard', '{"text": "grandmother", "subtext": "family member"}', '{"text": "abuela", "phonetic": "/ˈɡrænˌmʌðər/"}', null, null),
('00000003-0006-0001-0003-000000000001', '00000002-0000-0000-0006-000000000001', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''hermana'' en inglés?"}', '{"text": "sister"}', '["brother", "cousin", "daughter"]', '{"es": "''Sister'' significa hermana. ''Brother'' es hermano, ''cousin'' es primo/a y ''daughter'' es hija."}'),
('00000003-0006-0001-0004-000000000001', '00000002-0000-0000-0006-000000000001', 4, 'multiple_choice', '{"text": "What do you call your mother''s brother?"}', '{"text": "uncle"}', '["aunt", "cousin", "grandfather"]', '{"es": "El hermano de tu madre es tu tío (uncle). ''Aunt'' es tía, ''cousin'' es primo/a."}'),
('00000003-0006-0001-0005-000000000001', '00000002-0000-0000-0006-000000000001', 5, 'fill_blank', '{"text": "My father''s mother is my ___ ."}', '{"text": "grandmother", "accepted": ["grandmother", "grandma"]}', null, '{"es": "La madre de tu padre es tu abuela. En inglés ''grandmother'' o informalmente ''grandma''."}'),
('00000003-0006-0001-0006-000000000001', '00000002-0000-0000-0006-000000000001', 6, 'fill_blank', '{"text": "I have one brother and one ___ . (hermana)"}', '{"text": "sister", "accepted": ["sister"]}', null, '{"es": "''Sister'' significa hermana. ''Brother'' significa hermano."}'),
('00000003-0006-0001-0007-000000000001', '00000002-0000-0000-0006-000000000001', 7, 'translation', '{"text": "Mi tía tiene tres hijos."}', '{"text": "My aunt has three sons.", "accepted": ["My aunt has three sons.", "My aunt has three children."]}', null, '{"es": "''Aunt'' es tía. ''Sons'' son hijos varones. También puedes decir ''children'' para hijos en general."}'),
('00000003-0006-0001-0008-000000000001', '00000002-0000-0000-0006-000000000001', 8, 'translation', '{"text": "Tengo dos primos y una prima."}', '{"text": "I have two cousins and one cousin.", "accepted": ["I have three cousins.", "I have two male cousins and one female cousin."]}', null, '{"es": "En inglés ''cousin'' no cambia de género. Puedes simplificar diciendo ''I have three cousins''."}'),

('00000003-0006-0002-0001-000000000001', '00000002-0000-0000-0006-000000000002', 1, 'flashcard', '{"text": "sibling", "subtext": "general term for brother or sister"}', '{"text": "hermano/a (en general)", "phonetic": "/ˈsɪblɪŋ/"}', null, null),
('00000003-0006-0002-0002-000000000001', '00000002-0000-0000-0006-000000000002', 2, 'flashcard', '{"text": "only child", "subtext": "a child with no brothers or sisters"}', '{"text": "hijo/hija único/a", "phonetic": "/ˈoʊnli tʃaɪld/"}', null, null),
('00000003-0006-0002-0003-000000000001', '00000002-0000-0000-0006-000000000002', 3, 'multiple_choice', '{"text": "¿Cómo dices ''No tengo hermanos'' en inglés?"}', '{"text": "I don''t have any siblings."}', '["I have any siblings.", "I not have siblings.", "I haven''t siblings."]', '{"es": "La negación correcta es ''I don''t have any siblings.'' Usamos ''don''t have'' para la negación de ''have''."}'),
('00000003-0006-0002-0004-000000000001', '00000002-0000-0000-0006-000000000002', 4, 'multiple_choice', '{"text": "''My sister is 10 years old.'' What does this mean?"}', '{"text": "Mi hermana tiene 10 años."}', '["Mi hermana es de 10.", "Mi hermana está 10 años.", "Mis hermanas tienen 10 años."]', '{"es": "En inglés usamos ''is + número + years old'' para expresar la edad. Corresponde a ''tiene X años'' en español."}'),
('00000003-0006-0002-0005-000000000001', '00000002-0000-0000-0006-000000000002', 5, 'fill_blank', '{"text": "I ___ a brother. He is 18 years old."}', '{"text": "have", "accepted": ["have"]}', null, '{"es": "Usamos ''have'' con ''I'' para expresar posesión. ''I have a brother'' = Tengo un hermano."}'),
('00000003-0006-0002-0006-000000000001', '00000002-0000-0000-0006-000000000002', 6, 'fill_blank', '{"text": "My grandmother ___ 80 years old."}', '{"text": "is", "accepted": ["is"]}', null, '{"es": "Para expresar edad en inglés usamos el verbo ''to be''. ''She is 80 years old'' = Ella tiene 80 años."}'),
('00000003-0006-0002-0007-000000000001', '00000002-0000-0000-0006-000000000002', 7, 'translation', '{"text": "Tengo dos hermanos y no tengo hermanas."}', '{"text": "I have two brothers and I don''t have any sisters.", "accepted": ["I have two brothers and no sisters."]}', null, '{"es": "Usamos ''I have'' para lo que tenemos y ''I don''t have'' para lo que no tenemos."}'),
('00000003-0006-0002-0008-000000000001', '00000002-0000-0000-0006-000000000002', 8, 'translation', '{"text": "Soy hijo único. No tengo hermanos."}', '{"text": "I am an only child. I don''t have any siblings.", "accepted": ["I''m an only child. I don''t have siblings."]}', null, '{"es": "''Only child'' significa hijo único. Recuerda usar ''an'' antes de ''only'' porque empieza con vocal."}'),

('00000003-0006-0003-0001-000000000001', '00000002-0000-0000-0006-000000000003', 1, 'flashcard', '{"text": "my", "subtext": "possessive adjective"}', '{"text": "mi / mis", "phonetic": "/maɪ/"}', null, null),
('00000003-0006-0003-0002-000000000001', '00000002-0000-0000-0006-000000000003', 2, 'flashcard', '{"text": "their", "subtext": "possessive adjective (plural)"}', '{"text": "su / sus (de ellos)", "phonetic": "/ðɛr/"}', null, null),
('00000003-0006-0003-0003-000000000001', '00000002-0000-0000-0006-000000000003', 3, 'multiple_choice', '{"text": "María has a dog. ___ dog is small."}', '{"text": "Her"}', '["His", "My", "Our"]', '{"es": "María es mujer, entonces usamos ''Her'' (su de ella). ''His'' sería para un hombre."}'),
('00000003-0006-0003-0004-000000000001', '00000002-0000-0000-0006-000000000003', 4, 'multiple_choice', '{"text": "¿Cómo se dice ''el nombre de mi padre'' en inglés?"}', '{"text": "my father''s name"}', '["the name of my father", "my fathers name", "father my name"]', '{"es": "En inglés usamos apóstrofo-s: ''father''s name''. Aunque ''the name of my father'' es correcto, la forma con apóstrofo es más natural."}'),
('00000003-0006-0003-0005-000000000001', '00000002-0000-0000-0006-000000000003', 5, 'fill_blank', '{"text": "___ mother is a doctor. (Su mamá de Juan)"}', '{"text": "His", "accepted": ["His"]}', null, '{"es": "Juan es hombre, entonces usamos ''His'' para indicar posesión de él. ''His mother'' = su mamá (de él)."}'),
('00000003-0006-0003-0006-000000000001', '00000002-0000-0000-0006-000000000003', 6, 'fill_blank', '{"text": "My sister''s ___ is Carlos. (nombre)"}', '{"text": "husband", "accepted": ["husband", "name"]}', null, '{"es": "''Sister''s husband'' significa el esposo de mi hermana. El apóstrofo-s indica posesión."}'),
('00000003-0006-0003-0007-000000000001', '00000002-0000-0000-0006-000000000003', 7, 'translation', '{"text": "El nombre de mi abuela es Rosa."}', '{"text": "My grandmother''s name is Rosa.", "accepted": ["My grandmother''s name is Rosa."]}', null, '{"es": "Usamos apóstrofo-s para expresar posesión: ''grandmother''s name'' = el nombre de la abuela."}'),
('00000003-0006-0003-0008-000000000001', '00000002-0000-0000-0006-000000000003', 8, 'translation', '{"text": "Su hermano (de ella) es alto y su hermana (de ella) es baja."}', '{"text": "Her brother is tall and her sister is short.", "accepted": ["Her brother is tall and her sister is short."]}', null, '{"es": "Usamos ''her'' para la posesión de ella. Tanto ''her brother'' como ''her sister'' usan el mismo posesivo."}'),

('00000003-0006-0004-0001-000000000001', '00000002-0000-0000-0006-000000000004', 1, 'flashcard', '{"text": "kind", "subtext": "personality adjective"}', '{"text": "amable / bondadoso", "phonetic": "/kaɪnd/"}', null, null),
('00000003-0006-0004-0002-000000000001', '00000002-0000-0000-0006-000000000004', 2, 'flashcard', '{"text": "engineer", "subtext": "profession"}', '{"text": "ingeniero/a", "phonetic": "/ˌɛndʒɪˈnɪər/"}', null, null),
('00000003-0006-0004-0003-000000000001', '00000002-0000-0000-0006-000000000004', 3, 'multiple_choice', '{"text": "''She has brown eyes.'' What does ''brown'' mean here?"}', '{"text": "cafés / marrón"}', '["azules", "verdes", "negros"]', '{"es": "''Brown'' significa marrón o café. ''She has brown eyes'' = Ella tiene ojos cafés."}'),
('00000003-0006-0004-0004-000000000001', '00000002-0000-0000-0006-000000000004', 4, 'multiple_choice', '{"text": "My dad is a doctor. ___ is very smart."}', '{"text": "He"}', '["She", "They", "We"]', '{"es": "''Dad'' (papá) es masculino, entonces usamos el pronombre ''He'' (él) para referirnos a él."}'),
('00000003-0006-0004-0005-000000000001', '00000002-0000-0000-0006-000000000004', 5, 'fill_blank', '{"text": "My mom is a ___. She works at a school. (maestra)"}', '{"text": "teacher", "accepted": ["teacher"]}', null, '{"es": "''Teacher'' significa maestro/a. Usamos ''is a teacher'' para decir la profesión de alguien."}'),
('00000003-0006-0004-0006-000000000001', '00000002-0000-0000-0006-000000000004', 6, 'fill_blank', '{"text": "She has ___ hair and blue eyes. (cabello rubio)"}', '{"text": "blond", "accepted": ["blond", "blonde"]}', null, '{"es": "''Blond'' o ''blonde'' significa rubio. Se usa ''blond'' para hombres y ''blonde'' para mujeres aunque ambas formas son aceptadas."}'),
('00000003-0006-0004-0007-000000000001', '00000002-0000-0000-0006-000000000004', 7, 'translation', '{"text": "Mi mamá es maestra. Ella tiene 45 años y es muy amable."}', '{"text": "My mom is a teacher. She is 45 years old and very kind.", "accepted": ["My mom is a teacher. She is 45 years old and very kind."]}', null, '{"es": "''Kind'' significa amable. Combinamos profesión, edad y personalidad para una descripción completa."}'),
('00000003-0006-0004-0008-000000000001', '00000002-0000-0000-0006-000000000004', 8, 'translation', '{"text": "Mi abuelo tiene 70 años. Él tiene cabello blanco y es muy simpático."}', '{"text": "My grandfather is 70 years old. He has white hair and is very friendly.", "accepted": ["My grandfather is 70 years old. He has white hair and is very friendly."]}', null, '{"es": "''White hair'' es cabello blanco. ''Friendly'' es simpático. Usamos ''He'' para referirnos al abuelo."}');

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0007-000000000001', '00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 1, 'frutas-verduras', '{"en": "Fruits and Vegetables", "es": "Frutas y Verduras"}', '{"en": "Learn vocabulary for fruits and vegetables.", "es": "Aprende vocabulario de frutas y verduras."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás los nombres de las frutas y verduras más comunes en inglés. Este vocabulario es esencial para ir al supermercado, pedir comida en un restaurante o simplemente hablar sobre lo que comes en el día a día.", "sections": [{"type": "explanation", "title": "FRUTAS Y VERDURAS EN INGLÉS", "text": "En inglés, las frutas y verduras generalmente no tienen género. Cuando usamos el artículo indefinido, decimos ''an apple'' (una manzana) porque ''apple'' empieza con vocal. Para el plural simplemente añadimos una ''s'' o ''es'' al final: ''apples'', ''tomatoes''. Para expresar que te gusta algo, usamos ''I like'' seguido del nombre en plural: ''I like apples''.''}"}, {"type": "table", "title": "FRUTAS Y VERDURAS", "headers": ["English", "Español", "Artículo"], "rows": [["apple", "manzana", "an apple"], ["banana", "plátano / banana", "a banana"], ["orange", "naranja", "an orange"], ["strawberry", "fresa", "a strawberry"], ["grape", "uva", "a grape"], ["tomato", "tomate", "a tomato"], ["potato", "papa / patata", "a potato"], ["carrot", "zanahoria", "a carrot"], ["onion", "cebolla", "an onion"], ["lettuce", "lechuga", "lettuce (no article)"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I eat an apple every day.", "es": "Como una manzana todos los días."}, {"en": "Do you like bananas?", "es": "¿Te gustan los plátanos?"}, {"en": "We need tomatoes and onions.", "es": "Necesitamos tomates y cebollas."}, {"en": "I don''t like lettuce.", "es": "No me gusta la lechuga."}]}, {"type": "note", "variant": "info", "text": "''Lettuce'' es un sustantivo incontable (uncountable noun) en inglés, por lo que no se usa con artículo indefinido ni se pluraliza: decimos ''some lettuce'' o simplemente ''lettuce'', nunca ''a lettuce'' o ''lettuces'' en la mayoría de contextos."}]}', true),
('00000002-0000-0000-0007-000000000002', '00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 2, 'carnes-lacteos', '{"en": "Meats, Dairy and Proteins", "es": "Carnes, Lácteos y Proteínas"}', '{"en": "Learn vocabulary for meats, dairy products, and other proteins.", "es": "Aprende vocabulario de carnes, lácteos y otras proteínas."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás el vocabulario de carnes, productos lácteos y otras fuentes de proteína en inglés. Estos alimentos son parte fundamental de la dieta diaria y es importante saber cómo pedirlos o identificarlos en el menú de un restaurante.", "sections": [{"type": "explanation", "title": "SUSTANTIVOS CONTABLES E INCONTABLES", "text": "Algunos alimentos en inglés son contables (''an egg'', ''two eggs'') y otros son incontables (''rice'', ''milk'', ''bread''). Los incontables no se usan con artículos indefinidos y no tienen plural. Para expresar una cantidad de algo incontable usamos expresiones como ''a piece of bread'' (un pedazo de pan), ''a glass of milk'' (un vaso de leche) o ''a bowl of rice'' (un tazón de arroz)."}, {"type": "table", "title": "CARNES, LÁCTEOS Y PROTEÍNAS", "headers": ["English", "Español", "Tipo"], "rows": [["chicken", "pollo", "carne"], ["beef", "carne de res", "carne"], ["fish", "pescado", "carne/proteína"], ["eggs", "huevos", "proteína"], ["milk", "leche", "lácteo"], ["cheese", "queso", "lácteo"], ["yogurt", "yogur", "lácteo"], ["bread", "pan", "carbohidrato"], ["rice", "arroz", "carbohidrato"], ["pasta", "pasta", "carbohidrato"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I eat chicken and rice for lunch.", "es": "Como pollo y arroz en el almuerzo."}, {"en": "She drinks a glass of milk every morning.", "es": "Ella toma un vaso de leche cada mañana."}, {"en": "Would you like some bread and cheese?", "es": "¿Le gustaría algo de pan y queso?"}]}, {"type": "note", "variant": "tip", "text": "''Beef'' se refiere específicamente a la carne de res. ''Meat'' es el término general para carne. Entonces ''chicken'' es pollo (no ''chicken meat'') y ''fish'' es pescado. Solo la carne de res se llama ''beef''."}]}', true),
('00000002-0000-0000-0007-000000000003', '00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 3, 'bebidas', '{"en": "Drinks", "es": "Bebidas"}', '{"en": "Learn vocabulary for drinks and how to order them.", "es": "Aprende vocabulario de bebidas y cómo pedirlas."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás los nombres de las bebidas más comunes en inglés y las frases esenciales para ordenar una bebida en un café, restaurante o bar. Saber pedir una bebida correctamente es una de las habilidades más prácticas del inglés cotidiano.", "sections": [{"type": "explanation", "title": "CÓMO PEDIR UNA BEBIDA", "text": "En inglés hay varias formas de pedir una bebida. La más educada y común es usar ''I''d like'' (Me gustaría), que es la contracción de ''I would like''. También puedes usar ''Can I have...?'' (¿Puedo tener...?) o simplemente ''I want'' aunque esta última es más directa y puede sonar menos cortés. Siempre añade ''please'' al final para ser educado/a."}, {"type": "table", "title": "BEBIDAS COMUNES", "headers": ["English", "Español", "Ejemplo"], "rows": [["water", "agua", "a glass of water"], ["coffee", "café", "a cup of coffee"], ["tea", "té", "a cup of tea"], ["juice", "jugo / zumo", "orange juice"], ["soda", "refresco / gaseosa", "a can of soda"], ["milk", "leche", "a glass of milk"], ["beer", "cerveza", "a cold beer"], ["wine", "vino", "a glass of wine"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "Pedir educadamente", "en": "I''d like a coffee, please.", "es": "Me gustaría un café, por favor."}, {"label": "Preguntar", "en": "Can I have a glass of water?", "es": "¿Puedo tener un vaso de agua?"}, {"label": "Ofrecer", "en": "Would you like some tea?", "es": "¿Le gustaría algo de té?"}, {"label": "Negativo", "en": "I don''t drink beer.", "es": "No tomo cerveza."}]}, {"type": "note", "variant": "tip", "text": "''I''d like'' es la forma más educada y más usada para pedir algo en inglés. Memoriza esta frase: ''I''d like a ___, please.'' Te será útil en cafeterías, restaurantes y cualquier lugar donde ordenes algo."}]}', true),
('00000002-0000-0000-0007-000000000004', '00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 4, 'en-el-restaurante', '{"en": "At the Restaurant", "es": "En el Restaurante"}', '{"en": "Learn phrases for eating out at a restaurant.", "es": "Aprende frases para comer en un restaurante."}', 'conversation', 40, 18, '{"intro": "En esta lección aprenderás las frases más importantes para desenvolverte en un restaurante de habla inglesa. Desde pedir una mesa hasta pagar la cuenta, tendrás el vocabulario necesario para disfrutar de una comida sin dificultades.", "sections": [{"type": "explanation", "title": "EN EL RESTAURANTE", "text": "Cuando vas a un restaurante en inglés, hay una secuencia típica de interacciones: llegada y solicitud de mesa, lectura del menú, orden de la comida, y finalmente pedir la cuenta. En cada etapa hay frases específicas que son muy comunes. El mesero se llama ''waiter'' si es hombre y ''waitress'' si es mujer, aunque ''server'' es el término neutro más moderno."}, {"type": "table", "title": "FRASES EN EL RESTAURANTE", "headers": ["Situación", "Frase en inglés", "Español"], "rows": [["Pedir mesa", "A table for two, please.", "Una mesa para dos, por favor."], ["Pedir menú", "Can we see the menu?", "¿Podemos ver el menú?"], ["Ordenar", "I''d like the chicken, please.", "Me gustaría el pollo, por favor."], ["Pedir cuenta", "Can we have the bill, please?", "¿Nos puede traer la cuenta?"], ["Llamar mesero", "Excuse me!", "¡Disculpe!"], ["Está delicioso", "This is delicious!", "¡Está delicioso!"], ["Pedir recomendación", "What do you recommend?", "¿Qué recomienda?"]]}, {"type": "examples", "title": "DIÁLOGO EN EL RESTAURANTE", "items": [{"label": "Cliente", "en": "Excuse me! Can we have the bill, please?", "es": "¡Disculpe! ¿Nos puede traer la cuenta, por favor?"}, {"label": "Mesero", "en": "Of course! Are you paying together or separately?", "es": "¡Por supuesto! ¿Van a pagar juntos o por separado?"}, {"label": "Cliente", "en": "Together, please. This meal was delicious!", "es": "Juntos, por favor. ¡La comida estuvo deliciosa!"}]}, {"type": "note", "variant": "info", "text": "En los países de habla inglesa, especialmente en EE.UU., es costumbre dejar propina (''tip'') al mesero. La propina estándar es del 15-20% del total de la cuenta. En UK la propina es menos obligatoria pero igualmente apreciada."}]}', true),
('00000002-0000-0000-0007-000000000005', '00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 5, 'me-gusta', '{"en": "I Like / I Don''t Like", "es": "Me Gusta / No Me Gusta"}', '{"en": "Learn to express likes and dislikes about food.", "es": "Aprende a expresar gustos y preferencias sobre comida."}', 'grammar', 40, 15, '{"intro": "En esta lección aprenderás a expresar tus gustos y preferencias en inglés usando verbos como ''like'', ''love'' y ''hate''. También aprenderás a hacer preguntas sobre los gustos de otras personas, lo cual es esencial para tener conversaciones más interesantes.", "sections": [{"type": "explanation", "title": "EXPRESAR GUSTOS EN INGLÉS", "text": "En inglés usamos varios verbos para expresar diferentes grados de preferencia. A diferencia del español donde decimos ''me gusta el café'', en inglés decimos ''I like coffee'' sin el pronombre de objeto indirecto. Los verbos ''like'', ''love'' y ''hate'' se siguen directamente del sustantivo (con el artículo si es necesario) o de otro verbo en -ing."}, {"type": "table", "title": "VERBOS DE GUSTO Y PREFERENCIA", "headers": ["Inglés", "Español", "Intensidad"], "rows": [["I love...", "Me encanta...", "muy positivo"], ["I like...", "Me gusta...", "positivo"], ["I don''t mind...", "No me molesta...", "neutral"], ["I don''t like...", "No me gusta...", "negativo"], ["I hate...", "Odio... / Detesto...", "muy negativo"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I love pizza! It''s my favorite food.", "es": "¡Me encanta la pizza! Es mi comida favorita."}, {"en": "I don''t like onions. They are too strong.", "es": "No me gustan las cebollas. Son demasiado fuertes."}, {"label": "Pregunta", "en": "Do you like spicy food?", "es": "¿Te gusta la comida picante?"}, {"label": "Respuesta", "en": "Yes, I love it! / No, I hate it.", "es": "¡Sí, me encanta! / No, la odio."}]}, {"type": "note", "variant": "tip", "text": "Para hacer una pregunta sobre gustos usa ''Do you like + sustantivo?''. Para responder en positivo: ''Yes, I do.'' o ''Yes, I love it.''. Para responder en negativo: ''No, I don''t.'' o ''No, I hate it.''."}]}', true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0007-0001-0001-000000000001', '00000002-0000-0000-0007-000000000001', 1, 'flashcard', '{"text": "apple", "subtext": "fruit"}', '{"text": "manzana", "phonetic": "/ˈæpəl/"}', null, null),
('00000003-0007-0001-0002-000000000001', '00000002-0000-0000-0007-000000000001', 2, 'flashcard', '{"text": "strawberry", "subtext": "fruit"}', '{"text": "fresa", "phonetic": "/ˈstrɔːbɛri/"}', null, null),
('00000003-0007-0001-0003-000000000001', '00000002-0000-0000-0007-000000000001', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''zanahoria'' en inglés?"}', '{"text": "carrot"}', '["potato", "onion", "lettuce"]', '{"es": "''Carrot'' significa zanahoria. ''Potato'' es papa, ''onion'' es cebolla y ''lettuce'' es lechuga."}'),
('00000003-0007-0001-0004-000000000001', '00000002-0000-0000-0007-000000000001', 4, 'multiple_choice', '{"text": "Which of these is a vegetable?"}', '{"text": "potato"}', '["banana", "grape", "strawberry"]', '{"es": "''Potato'' (papa) es una verdura. Los demás son frutas: banana, grape (uva) y strawberry (fresa)."}'),
('00000003-0007-0001-0005-000000000001', '00000002-0000-0000-0007-000000000001', 5, 'fill_blank', '{"text": "I eat ___ apple every day. (una)"}', '{"text": "an", "accepted": ["an"]}', null, '{"es": "Usamos ''an'' (no ''a'') antes de palabras que empiezan con vocal. ''Apple'' empieza con la vocal ''a''."}'),
('00000003-0007-0001-0006-000000000001', '00000002-0000-0000-0007-000000000001', 6, 'fill_blank', '{"text": "We need tomatoes and ___ for the salad. (cebollas)"}', '{"text": "onions", "accepted": ["onions"]}', null, '{"es": "''Onion'' (cebolla) en plural es ''onions''. Las verduras son contables y se pluralizan añadiendo -s o -es."}'),
('00000003-0007-0001-0007-000000000001', '00000002-0000-0000-0007-000000000001', 7, 'translation', '{"text": "Me gustan las fresas y las uvas."}', '{"text": "I like strawberries and grapes.", "accepted": ["I like strawberries and grapes."]}', null, '{"es": "En inglés no decimos ''me gustan'' sino ''I like''. Los sustantivos van en plural para expresar gustos generales."}'),
('00000003-0007-0001-0008-000000000001', '00000002-0000-0000-0007-000000000001', 8, 'translation', '{"text": "Necesito plátanos, manzanas y lechuga del supermercado."}', '{"text": "I need bananas, apples, and lettuce from the supermarket.", "accepted": ["I need bananas, apples and lettuce from the supermarket."]}', null, '{"es": "''Lettuce'' no lleva artículo cuando se habla en general. ''Supermarket'' es supermercado en inglés."}'),

('00000003-0007-0002-0001-000000000001', '00000002-0000-0000-0007-000000000002', 1, 'flashcard', '{"text": "chicken", "subtext": "meat / protein"}', '{"text": "pollo", "phonetic": "/ˈtʃɪkɪn/"}', null, null),
('00000003-0007-0002-0002-000000000001', '00000002-0000-0000-0007-000000000002', 2, 'flashcard', '{"text": "cheese", "subtext": "dairy product"}', '{"text": "queso", "phonetic": "/tʃiːz/"}', null, null),
('00000003-0007-0002-0003-000000000001', '00000002-0000-0000-0007-000000000002', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''carne de res'' en inglés?"}', '{"text": "beef"}', '["chicken", "fish", "pork"]', '{"es": "''Beef'' es la carne de res. ''Chicken'' es pollo, ''fish'' es pescado y ''pork'' es cerdo."}'),
('00000003-0007-0002-0004-000000000001', '00000002-0000-0000-0007-000000000002', 4, 'multiple_choice', '{"text": "Which food is a dairy product?"}', '{"text": "yogurt"}', '["rice", "chicken", "bread"]', '{"es": "''Yogurt'' es un producto lácteo. ''Rice'' es arroz, ''chicken'' es pollo y ''bread'' es pan."}'),
('00000003-0007-0002-0005-000000000001', '00000002-0000-0000-0007-000000000002', 5, 'fill_blank', '{"text": "I have ___ and toast for breakfast. (huevos)"}', '{"text": "eggs", "accepted": ["eggs"]}', null, '{"es": "''Eggs'' son huevos. Es una proteína popular para el desayuno junto con ''toast'' (pan tostado)."}'),
('00000003-0007-0002-0006-000000000001', '00000002-0000-0000-0007-000000000002', 6, 'fill_blank', '{"text": "She drinks a glass of ___ every morning. (leche)"}', '{"text": "milk", "accepted": ["milk"]}', null, '{"es": "''Milk'' es leche. Es un sustantivo incontable: ''a glass of milk'' = un vaso de leche."}'),
('00000003-0007-0002-0007-000000000001', '00000002-0000-0000-0007-000000000002', 7, 'translation', '{"text": "Como pollo con arroz para el almuerzo."}', '{"text": "I eat chicken and rice for lunch.", "accepted": ["I eat chicken with rice for lunch."]}', null, '{"es": "''Chicken'' es pollo y ''rice'' es arroz. ''Lunch'' es el almuerzo. Ambos son incontables en inglés."}'),
('00000003-0007-0002-0008-000000000001', '00000002-0000-0000-0007-000000000002', 8, 'translation', '{"text": "¿Quieres pan con queso?"}', '{"text": "Would you like some bread and cheese?", "accepted": ["Do you want some bread and cheese?", "Would you like bread and cheese?"]}', null, '{"es": "''Would you like'' es más educado que ''Do you want''. Usamos ''some'' antes de sustantivos incontables."}'),

('00000003-0007-0003-0001-000000000001', '00000002-0000-0000-0007-000000000003', 1, 'flashcard', '{"text": "coffee", "subtext": "hot drink"}', '{"text": "café", "phonetic": "/ˈkɒfi/"}', null, null),
('00000003-0007-0003-0002-000000000001', '00000002-0000-0000-0007-000000000003', 2, 'flashcard', '{"text": "juice", "subtext": "drink"}', '{"text": "jugo / zumo", "phonetic": "/dʒuːs/"}', null, null),
('00000003-0007-0003-0003-000000000001', '00000002-0000-0000-0007-000000000003', 3, 'multiple_choice', '{"text": "¿Cuál es la forma más educada de pedir una bebida?"}', '{"text": "I''d like a water, please."}', '["I want water.", "Give me water.", "Water!"]', '{"es": "''I''d like'' (Me gustaría) es la forma más educada. Siempre añade ''please'' al final para ser cortés."}'),
('00000003-0007-0003-0004-000000000001', '00000002-0000-0000-0007-000000000003', 4, 'multiple_choice', '{"text": "What is the English word for ''té''?"}', '{"text": "tea"}', '["coffee", "soda", "juice"]', '{"es": "''Tea'' significa té. Se pronuncia /tiː/."}'),
('00000003-0007-0003-0005-000000000001', '00000002-0000-0000-0007-000000000003', 5, 'fill_blank', '{"text": "I''d like a cup of ___, please. (café)"}', '{"text": "coffee", "accepted": ["coffee"]}', null, '{"es": "''Coffee'' es café. Decimos ''a cup of coffee'' (una taza de café)."}'),
('00000003-0007-0003-0006-000000000001', '00000002-0000-0000-0007-000000000003', 6, 'fill_blank', '{"text": "Can I have a glass of ___, please? (agua)"}', '{"text": "water", "accepted": ["water"]}', null, '{"es": "''Water'' es agua. ''A glass of water'' = un vaso de agua."}'),
('00000003-0007-0003-0007-000000000001', '00000002-0000-0000-0007-000000000003', 7, 'translation', '{"text": "Me gustaría un jugo de naranja, por favor."}', '{"text": "I''d like an orange juice, please.", "accepted": ["I''d like orange juice, please."]}', null, '{"es": "''I''d like'' = Me gustaría. ''Orange juice'' = jugo de naranja. Recuerda ''please'' al final."}'),
('00000003-0007-0003-0008-000000000001', '00000002-0000-0000-0007-000000000003', 8, 'translation', '{"text": "¿Te gustaría algo de té o café?"}', '{"text": "Would you like some tea or coffee?", "accepted": ["Would you like tea or coffee?"]}', null, '{"es": "''Would you like'' es la forma interrogativa educada para ofrecer algo. ''Some'' se usa para cantidades no especificadas."}'),

('00000003-0007-0004-0001-000000000001', '00000002-0000-0000-0007-000000000004', 1, 'flashcard', '{"text": "waiter", "subtext": "restaurant staff (male)"}', '{"text": "mesero / camarero", "phonetic": "/ˈweɪtər/"}', null, null),
('00000003-0007-0004-0002-000000000001', '00000002-0000-0000-0007-000000000004', 2, 'flashcard', '{"text": "bill", "subtext": "at a restaurant"}', '{"text": "cuenta", "phonetic": "/bɪl/"}', null, null),
('00000003-0007-0004-0003-000000000001', '00000002-0000-0000-0007-000000000004', 3, 'multiple_choice', '{"text": "¿Cómo pides una mesa para dos personas en un restaurante?"}', '{"text": "A table for two, please."}', '["Two tables, please.", "I want two seats.", "Table two, please."]', '{"es": "La frase correcta es ''A table for two, please.'' Significa ''Una mesa para dos personas, por favor.''"}'),
('00000003-0007-0004-0004-000000000001', '00000002-0000-0000-0007-000000000004', 4, 'multiple_choice', '{"text": "How do you ask for the check/bill at a restaurant?"}', '{"text": "Can we have the bill, please?"}', '["Where is the money?", "I need to pay now.", "Bring me the bill!"]', '{"es": "La forma correcta y educada es ''Can we have the bill, please?'' En EE.UU. también se dice ''check'' en lugar de ''bill''."}'),
('00000003-0007-0004-0005-000000000001', '00000002-0000-0000-0007-000000000004', 5, 'fill_blank', '{"text": "Excuse me! Can I see the ___, please? (menú)"}', '{"text": "menu", "accepted": ["menu"]}', null, '{"es": "''Menu'' en inglés se pronuncia /ˈmɛnjuː/. Pedimos ver el menú para elegir nuestra comida."}'),
('00000003-0007-0004-0006-000000000001', '00000002-0000-0000-0007-000000000004', 6, 'fill_blank', '{"text": "I''d like the fish, ___. (por favor)"}', '{"text": "please", "accepted": ["please"]}', null, '{"es": "Siempre añade ''please'' al final de tus pedidos para ser educado en inglés."}'),
('00000003-0007-0004-0007-000000000001', '00000002-0000-0000-0007-000000000004', 7, 'translation', '{"text": "¡Disculpe! ¿Qué recomienda usted?"}', '{"text": "Excuse me! What do you recommend?", "accepted": ["Excuse me! What do you recommend?"]}', null, '{"es": "''Excuse me'' se usa para llamar la atención de alguien. ''What do you recommend?'' pide una recomendación."}'),
('00000003-0007-0004-0008-000000000001', '00000002-0000-0000-0007-000000000004', 8, 'translation', '{"text": "La comida estuvo deliciosa. ¿Nos puede traer la cuenta, por favor?"}', '{"text": "The food was delicious. Can we have the bill, please?", "accepted": ["The meal was delicious. Can we have the bill, please?"]}', null, '{"es": "''Delicious'' es delicioso. ''Can we have the bill'' es la forma de pedir la cuenta. ''Was'' es el pasado de ''is''."}'),

('00000003-0007-0005-0001-000000000001', '00000002-0000-0000-0007-000000000005', 1, 'flashcard', '{"text": "I love it!", "subtext": "expressing strong like"}', '{"text": "¡Me encanta!", "phonetic": "/aɪ lʌv ɪt/"}', null, null),
('00000003-0007-0005-0002-000000000001', '00000002-0000-0000-0007-000000000005', 2, 'flashcard', '{"text": "I hate it.", "subtext": "expressing strong dislike"}', '{"text": "Lo odio. / Lo detesto.", "phonetic": "/aɪ heɪt ɪt/"}', null, null),
('00000003-0007-0005-0003-000000000001', '00000002-0000-0000-0007-000000000005', 3, 'multiple_choice', '{"text": "¿Cómo dices ''No me gusta el brócoli'' en inglés?"}', '{"text": "I don''t like broccoli."}', '["I not like broccoli.", "I dislike of broccoli.", "I no like broccoli."]', '{"es": "La negación correcta es ''I don''t like''. Nunca uses ''I not like'' o ''I no like'' en inglés."}'),
('00000003-0007-0005-0004-000000000001', '00000002-0000-0000-0007-000000000005', 4, 'multiple_choice', '{"text": "''Do you like spicy food?'' — What is the correct answer?"}', '{"text": "Yes, I do. I love it!"}', '["Yes, I like.", "Yes, I am.", "Yes, I does."]', '{"es": "La respuesta correcta usa ''do'' porque la pregunta usa ''do''. ''Yes, I do'' confirma el gusto."}'),
('00000003-0007-0005-0005-000000000001', '00000002-0000-0000-0007-000000000005', 5, 'fill_blank', '{"text": "I ___ pizza! It''s my favorite. (me encanta)"}', '{"text": "love", "accepted": ["love"]}', null, '{"es": "''Love'' expresa un gusto muy intenso, más fuerte que ''like''. ''I love pizza'' = Me encanta la pizza."}'),
('00000003-0007-0005-0006-000000000001', '00000002-0000-0000-0007-000000000005', 6, 'fill_blank', '{"text": "___ you like sushi? (¿Te gusta...?)"}', '{"text": "Do", "accepted": ["Do"]}', null, '{"es": "Para hacer preguntas con ''like'' usamos ''Do'' al inicio: ''Do you like...?'' Es el auxiliar para el presente simple."}'),
('00000003-0007-0005-0007-000000000001', '00000002-0000-0000-0007-000000000005', 7, 'translation', '{"text": "Me encanta el chocolate pero no me gusta la vainilla."}', '{"text": "I love chocolate but I don''t like vanilla.", "accepted": ["I love chocolate but I don''t like vanilla."]}', null, '{"es": "''Love'' para gusto intenso y ''don''t like'' para no gustar. ''But'' conecta los dos ideas contrastantes."}'),
('00000003-0007-0005-0008-000000000001', '00000002-0000-0000-0007-000000000005', 8, 'translation', '{"text": "¿Te gusta la comida italiana? A mí me encanta."}', '{"text": "Do you like Italian food? I love it.", "accepted": ["Do you like Italian food? I love it!"]}', null, '{"es": "''Italian food'' es comida italiana. Usamos ''it'' para referirnos a algo mencionado antes: ''I love it'' = me encanta (la comida italiana)."}');

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0008-000000000001', '00000001-0000-0000-0000-000000000008', '00000000-0000-0000-0001-000000000001', 1, 'partes-cuerpo', '{"en": "Parts of the Body", "es": "Partes del Cuerpo"}', '{"en": "Learn the names of body parts in English.", "es": "Aprende los nombres de las partes del cuerpo en inglés."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás los nombres de las principales partes del cuerpo en inglés. Este vocabulario es fundamental para hablar de salud, hacer ejercicio, ir al médico o simplemente comprender conversaciones cotidianas sobre el cuerpo humano.", "sections": [{"type": "explanation", "title": "PARTES DEL CUERPO EN INGLÉS", "text": "En inglés, cuando hablamos de las partes del cuerpo de una persona, generalmente usamos adjetivos posesivos (my, your, his, her) en lugar de artículos definidos como en español. Por ejemplo, en lugar de decir ''me duele la cabeza'', en inglés se dice ''my head hurts'' o ''I have a headache''. Para el plural de las partes del cuerpo, la mayoría añaden simplemente una ''s'': arms, legs, hands."}, {"type": "table", "title": "PARTES DEL CUERPO", "headers": ["English", "Español", "Plural"], "rows": [["head", "cabeza", "heads"], ["neck", "cuello", "necks"], ["shoulder", "hombro", "shoulders"], ["arm", "brazo", "arms"], ["hand", "mano", "hands"], ["fingers", "dedos (de la mano)", "fingers"], ["chest", "pecho", "chests"], ["back", "espalda", "backs"], ["leg", "pierna", "legs"], ["knee", "rodilla", "knees"], ["foot", "pie", "feet (irregular)"], ["toes", "dedos (del pie)", "toes"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I have two arms and two legs.", "es": "Tengo dos brazos y dos piernas."}, {"en": "My back hurts after work.", "es": "Mi espalda me duele después del trabajo."}, {"en": "She broke her knee playing soccer.", "es": "Ella se rompió la rodilla jugando fútbol."}]}, {"type": "note", "variant": "warning", "text": "''Foot'' (pie) tiene un plural irregular: ''feet''. No digas ''foots''. De la misma manera, ''fingers'' son los dedos de la MANO y ''toes'' son los dedos del PIE. No son intercambiables."}]}', true),
('00000002-0000-0000-0008-000000000002', '00000001-0000-0000-0000-000000000008', '00000000-0000-0000-0001-000000000001', 2, 'cara-sentidos', '{"en": "The Face and the Senses", "es": "La Cara y los Sentidos"}', '{"en": "Learn vocabulary for face parts and the five senses.", "es": "Aprende vocabulario de la cara y los cinco sentidos."}', 'vocabulary', 30, 12, '{"intro": "En esta lección aprenderás las partes de la cara en inglés y los verbos relacionados con los cinco sentidos. Saber estos términos te ayudará a describir a las personas y a entender conversaciones sobre percepciones y experiencias sensoriales.", "sections": [{"type": "explanation", "title": "LA CARA EN INGLÉS", "text": "Las partes de la cara son muy importantes en inglés para describir a las personas y para el vocabulario médico básico. Muchas partes de la cara vienen en pares (dos ojos, dos orejas, dos mejillas) y por eso frecuentemente las mencionamos en plural: ''her eyes are brown'' (sus ojos son cafés)."}, {"type": "table", "title": "PARTES DE LA CARA", "headers": ["English", "Español", "Ejemplo"], "rows": [["eye", "ojo", "brown eyes"], ["ear", "oreja / oído", "big ears"], ["nose", "nariz", "a small nose"], ["mouth", "boca", "a big mouth"], ["teeth", "dientes", "white teeth"], ["chin", "barbilla / mentón", "a strong chin"], ["cheek", "mejilla", "pink cheeks"]]}, {"type": "explanation", "title": "LOS CINCO SENTIDOS", "text": "Los cinco sentidos en inglés se expresan con verbos específicos. Nota que algunos tienen dos formas: ''see'' vs. ''look at'' (ver), ''hear'' vs. ''listen to'' (escuchar). ''See'' y ''hear'' son involuntarios (percepciones automáticas), mientras que ''look at'' y ''listen to'' son acciones intencionales."}, {"type": "table", "title": "LOS CINCO SENTIDOS", "headers": ["Sentido", "Verbo", "Ejemplo"], "rows": [["sight", "see / look at", "I can see the mountains."], ["hearing", "hear / listen to", "I can hear music."], ["smell", "smell", "I can smell coffee."], ["taste", "taste", "This tastes sweet."], ["touch", "touch / feel", "I can feel the cold."]]}, {"type": "note", "variant": "tip", "text": "''Teeth'' es el plural irregular de ''tooth'' (diente). No digas ''tooths''. Similarmente, usamos ''teeth'' cuando hablamos de los dientes en general, y ''a tooth'' para un diente específico."}]}', true),
('00000002-0000-0000-0008-000000000003', '00000001-0000-0000-0000-000000000008', '00000000-0000-0000-0001-000000000001', 3, 'sintomas-salud', '{"en": "Health Symptoms", "es": "Síntomas y Problemas de Salud"}', '{"en": "Learn to express health problems and symptoms in English.", "es": "Aprende a expresar problemas de salud y síntomas en inglés."}', 'conversation', 35, 15, '{"intro": "En esta lección aprenderás a hablar sobre problemas de salud y síntomas en inglés. Poder comunicar cómo te sientes cuando estás enfermo es una habilidad esencial, especialmente si viajas a un país de habla inglesa o si visitas a un médico que solo habla inglés.", "sections": [{"type": "explanation", "title": "EXPRESAR SÍNTOMAS EN INGLÉS", "text": "En inglés hay varias estructuras para expresar problemas de salud. La más común es ''I have a + nombre del problema'': ''I have a headache'' (Tengo dolor de cabeza). También usamos ''My + parte del cuerpo + hurts'': ''My stomach hurts'' (Me duele el estómago). Para describir cómo nos sentimos en general usamos ''I feel + adjetivo'': ''I feel sick'' (Me siento mal)."}, {"type": "table", "title": "PROBLEMAS DE SALUD COMUNES", "headers": ["Inglés", "Español", "Estructura"], "rows": [["I have a headache.", "Tengo dolor de cabeza.", "I have a + problema"], ["I have a fever.", "Tengo fiebre.", "I have a + problema"], ["I have a cold.", "Tengo un resfriado.", "I have a + problema"], ["I have a cough.", "Tengo tos.", "I have a + problema"], ["My stomach hurts.", "Me duele el estómago.", "My + cuerpo + hurts"], ["My back hurts.", "Me duele la espalda.", "My + cuerpo + hurts"], ["I feel sick.", "Me siento mal / enfermo.", "I feel + adjetivo"], ["I feel tired.", "Me siento cansado.", "I feel + adjetivo"], ["I feel dizzy.", "Me siento mareado.", "I feel + adjetivo"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I have a headache and a fever. I think I''m sick.", "es": "Tengo dolor de cabeza y fiebre. Creo que estoy enfermo."}, {"en": "My throat hurts and I have a cough.", "es": "Me duele la garganta y tengo tos."}, {"en": "I feel very tired today. I didn''t sleep well.", "es": "Me siento muy cansado hoy. No dormí bien."}]}, {"type": "note", "variant": "info", "text": "Para un dolor de cabeza usamos ''headache'' (una sola palabra). Para otros dolores usamos la estructura ''My [part] hurts'': ''My head hurts'' también funciona para dolor de cabeza. Pero ''I have a stomachache'' también existe como una sola palabra."}]}', true),
('00000002-0000-0000-0008-000000000004', '00000001-0000-0000-0000-000000000008', '00000000-0000-0000-0001-000000000001', 4, 'en-el-medico', '{"en": "At the Doctor''s", "es": "En el Médico"}', '{"en": "Learn phrases for a doctor''s appointment in English.", "es": "Aprende frases para una cita médica en inglés."}', 'conversation', 40, 18, '{"intro": "En esta lección aprenderás las frases más importantes para comunicarte durante una visita al médico en inglés. Desde pedir una cita hasta entender las instrucciones del doctor, tendrás el vocabulario necesario para manejar una situación médica básica en inglés.", "sections": [{"type": "explanation", "title": "EN EL CONSULTORIO MÉDICO", "text": "Cuando visitas a un médico en un país de habla inglesa, es importante saber describir tus síntomas con claridad. El médico te hará preguntas como ''What seems to be the problem?'' (¿Cuál parece ser el problema?) o ''Where does it hurt?'' (¿Dónde le duele?). También necesitas entender las instrucciones sobre medicamentos: ''Take this twice a day'' (Tome esto dos veces al día)."}, {"type": "table", "title": "VOCABULARIO MÉDICO", "headers": ["Inglés", "Español", "Categoría"], "rows": [["doctor", "médico / doctor", "persona"], ["nurse", "enfermero/a", "persona"], ["hospital", "hospital", "lugar"], ["clinic", "clínica", "lugar"], ["prescription", "receta médica", "documento"], ["appointment", "cita", "evento"], ["emergency", "emergencia", "situación"], ["pharmacy", "farmacia", "lugar"], ["medicine", "medicina / medicamento", "tratamiento"]]}, {"type": "examples", "title": "DIÁLOGO EN EL MÉDICO", "items": [{"label": "Doctor", "en": "What seems to be the problem?", "es": "¿Cuál parece ser el problema?"}, {"label": "Paciente", "en": "I have a fever and my throat hurts.", "es": "Tengo fiebre y me duele la garganta."}, {"label": "Doctor", "en": "How long have you had these symptoms?", "es": "¿Cuánto tiempo lleva con estos síntomas?"}, {"label": "Paciente", "en": "For two days. I also feel very tired.", "es": "Por dos días. También me siento muy cansado."}, {"label": "Doctor", "en": "I''ll write you a prescription. Take the medicine twice a day.", "es": "Le voy a dar una receta. Tome el medicamento dos veces al día."}]}, {"type": "note", "variant": "tip", "text": "Para pedir una cita médica por teléfono en inglés, di: ''I''d like to make an appointment with Dr. Smith, please.'' (Me gustaría hacer una cita con el Dr. Smith, por favor.) Si es urgente añade: ''It''s urgent.'' (Es urgente.)"}]}', true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0008-0001-0001-000000000001', '00000002-0000-0000-0008-000000000001', 1, 'flashcard', '{"text": "shoulder", "subtext": "body part"}', '{"text": "hombro", "phonetic": "/ˈʃoʊldər/"}', null, null),
('00000003-0008-0001-0002-000000000001', '00000002-0000-0000-0008-000000000001', 2, 'flashcard', '{"text": "knee", "subtext": "body part"}', '{"text": "rodilla", "phonetic": "/niː/"}', null, null),
('00000003-0008-0001-0003-000000000001', '00000002-0000-0000-0008-000000000001', 3, 'multiple_choice', '{"text": "¿Cuál es el plural correcto de ''foot'' (pie)?"}', '{"text": "feet"}', '["foots", "feets", "foot"]', '{"es": "''Foot'' tiene un plural irregular: ''feet''. No se dice ''foots''. Es un ejemplo de plural irregular en inglés."}'),
('00000003-0008-0001-0004-000000000001', '00000002-0000-0000-0008-000000000001', 4, 'multiple_choice', '{"text": "What do we call the fingers on our feet?"}', '{"text": "toes"}', '["fingers", "nails", "heels"]', '{"es": "Los dedos del pie se llaman ''toes'' en inglés. ''Fingers'' son solo los dedos de la mano."}'),
('00000003-0008-0001-0005-000000000001', '00000002-0000-0000-0008-000000000001', 5, 'fill_blank', '{"text": "I have two ___ and two legs. (brazos)"}', '{"text": "arms", "accepted": ["arms"]}', null, '{"es": "''Arms'' son brazos en plural. El singular es ''arm''. Tenemos dos brazos y dos piernas."}'),
('00000003-0008-0001-0006-000000000001', '00000002-0000-0000-0008-000000000001', 6, 'fill_blank', '{"text": "My ___ hurts after sitting all day. (espalda)"}', '{"text": "back", "accepted": ["back"]}', null, '{"es": "''Back'' significa espalda. La espalda nos duele cuando estamos sentados por mucho tiempo."}'),
('00000003-0008-0001-0007-000000000001', '00000002-0000-0000-0008-000000000001', 7, 'translation', '{"text": "Me duele la rodilla izquierda."}', '{"text": "My left knee hurts.", "accepted": ["My left knee hurts."]}', null, '{"es": "''Knee'' es rodilla y ''left'' es izquierdo. Usamos ''My + parte del cuerpo + hurts'' para expresar dolor."}'),
('00000003-0008-0001-0008-000000000001', '00000002-0000-0000-0008-000000000001', 8, 'translation', '{"text": "Ella se lastimó el hombro jugando tenis."}', '{"text": "She hurt her shoulder playing tennis.", "accepted": ["She hurt her shoulder playing tennis."]}', null, '{"es": "''Hurt'' significa lastimar. ''Her shoulder'' porque hablamos de ella. ''Playing tennis'' es jugando tenis."}'),

('00000003-0008-0002-0001-000000000001', '00000002-0000-0000-0008-000000000002', 1, 'flashcard', '{"text": "eye", "subtext": "face part / sense organ"}', '{"text": "ojo", "phonetic": "/aɪ/"}', null, null),
('00000003-0008-0002-0002-000000000001', '00000002-0000-0000-0008-000000000002', 2, 'flashcard', '{"text": "smell", "subtext": "one of the five senses"}', '{"text": "oler / olfato", "phonetic": "/smɛl/"}', null, null),
('00000003-0008-0002-0003-000000000001', '00000002-0000-0000-0008-000000000002', 3, 'multiple_choice', '{"text": "¿Cuál es el plural correcto de ''tooth'' (diente)?"}', '{"text": "teeth"}', '["tooths", "toothes", "tooth"]', '{"es": "''Tooth'' tiene un plural irregular: ''teeth''. Este es uno de los plurales más comunes que debes memorizar."}'),
('00000003-0008-0002-0004-000000000001', '00000002-0000-0000-0008-000000000002', 4, 'multiple_choice', '{"text": "Which verb is used for the sense of taste?"}', '{"text": "taste"}', '["hear", "see", "touch"]', '{"es": "''Taste'' es el verbo para el sentido del gusto. ''Hear'' es escuchar, ''see'' es ver y ''touch'' es tocar."}'),
('00000003-0008-0002-0005-000000000001', '00000002-0000-0000-0008-000000000002', 5, 'fill_blank', '{"text": "I can ___ the coffee from here. (oler)"}', '{"text": "smell", "accepted": ["smell"]}', null, '{"es": "''Smell'' significa oler. ''I can smell the coffee'' = Puedo oler el café desde aquí."}'),
('00000003-0008-0002-0006-000000000001', '00000002-0000-0000-0008-000000000002', 6, 'fill_blank', '{"text": "She has beautiful brown ___. (ojos)"}', '{"text": "eyes", "accepted": ["eyes"]}', null, '{"es": "''Eyes'' son ojos en plural. ''Brown eyes'' = ojos cafés / marrón."}'),
('00000003-0008-0002-0007-000000000001', '00000002-0000-0000-0008-000000000002', 7, 'translation', '{"text": "Ella tiene la nariz pequeña y la boca grande."}', '{"text": "She has a small nose and a big mouth.", "accepted": ["She has a small nose and a big mouth."]}', null, '{"es": "''Nose'' es nariz y ''mouth'' es boca. Usamos ''to have'' para describir características físicas."}'),
('00000003-0008-0002-0008-000000000001', '00000002-0000-0000-0008-000000000002', 8, 'translation', '{"text": "Puedo escuchar música y ver las estrellas."}', '{"text": "I can hear music and see the stars.", "accepted": ["I can hear music and see the stars."]}', null, '{"es": "''Hear'' es escuchar (involuntario) y ''see'' es ver (involuntario). ''Can'' expresa capacidad o percepción sensorial."}'),

('00000003-0008-0003-0001-000000000001', '00000002-0000-0000-0008-000000000003', 1, 'flashcard', '{"text": "headache", "subtext": "health problem"}', '{"text": "dolor de cabeza", "phonetic": "/ˈhɛdeɪk/"}', null, null),
('00000003-0008-0003-0002-000000000001', '00000002-0000-0000-0008-000000000003', 2, 'flashcard', '{"text": "fever", "subtext": "health symptom"}', '{"text": "fiebre", "phonetic": "/ˈfiːvər/"}', null, null),
('00000003-0008-0003-0003-000000000001', '00000002-0000-0000-0008-000000000003', 3, 'multiple_choice', '{"text": "¿Cómo dices ''Tengo un resfriado'' en inglés?"}', '{"text": "I have a cold."}', '["I am cold.", "I have cold.", "I feel a cold."]', '{"es": "''I have a cold'' es la expresión correcta para decir que tienes un resfriado. ''I am cold'' significa que tienes frío (temperatura)."}'),
('00000003-0008-0003-0004-000000000001', '00000002-0000-0000-0008-000000000003', 4, 'multiple_choice', '{"text": "''My stomach hurts.'' What does this mean?"}', '{"text": "Me duele el estómago."}', '["Mi estómago está sucio.", "Tengo hambre.", "Me gusta el estómago."]', '{"es": "''My stomach hurts'' = Me duele el estómago. La estructura ''My + parte del cuerpo + hurts'' expresa dolor."}'),
('00000003-0008-0003-0005-000000000001', '00000002-0000-0000-0008-000000000003', 5, 'fill_blank', '{"text": "I feel very ___. I need to rest. (cansado)"}', '{"text": "tired", "accepted": ["tired"]}', null, '{"es": "''Tired'' significa cansado. ''I feel tired'' = Me siento cansado. Usamos ''feel'' + adjetivo para describir cómo nos sentimos."}'),
('00000003-0008-0003-0006-000000000001', '00000002-0000-0000-0008-000000000003', 6, 'fill_blank', '{"text": "I have a ___ . My temperature is 39°C. (fiebre)"}', '{"text": "fever", "accepted": ["fever"]}', null, '{"es": "''Fever'' significa fiebre. Cuando la temperatura está alta, decimos ''I have a fever''."}'),
('00000003-0008-0003-0007-000000000001', '00000002-0000-0000-0008-000000000003', 7, 'translation', '{"text": "Tengo dolor de cabeza y me siento mareado."}', '{"text": "I have a headache and I feel dizzy.", "accepted": ["I have a headache and I feel dizzy."]}', null, '{"es": "''Headache'' es dolor de cabeza (una sola palabra). ''Dizzy'' significa mareado. ''I feel dizzy'' = Me siento mareado."}'),
('00000003-0008-0003-0008-000000000001', '00000002-0000-0000-0008-000000000003', 8, 'translation', '{"text": "Me duele la garganta y tengo tos."}', '{"text": "My throat hurts and I have a cough.", "accepted": ["My throat hurts and I have a cough."]}', null, '{"es": "''Throat'' es garganta. ''Cough'' es tos. Combinamos dos estructuras diferentes: ''My throat hurts'' y ''I have a cough''."}'),

('00000003-0008-0004-0001-000000000001', '00000002-0000-0000-0008-000000000004', 1, 'flashcard', '{"text": "prescription", "subtext": "medical document"}', '{"text": "receta médica", "phonetic": "/prɪˈskrɪpʃən/"}', null, null),
('00000003-0008-0004-0002-000000000001', '00000002-0000-0000-0008-000000000004', 2, 'flashcard', '{"text": "appointment", "subtext": "scheduled meeting with a doctor"}', '{"text": "cita (médica)", "phonetic": "/əˈpɔɪntmənt/"}', null, null),
('00000003-0008-0004-0003-000000000001', '00000002-0000-0000-0008-000000000004', 3, 'multiple_choice', '{"text": "The doctor says: ''What seems to be the problem?'' What does she want to know?"}', '{"text": "What health problem do you have?"}', '["What is your name?", "What medicine do you take?", "What is the date today?"]', '{"es": "''What seems to be the problem?'' es la manera como el médico pregunta qué problema de salud tienes. Es una pregunta muy común en inglés médico."}'),
('00000003-0008-0004-0004-000000000001', '00000002-0000-0000-0008-000000000004', 4, 'multiple_choice', '{"text": "The doctor says: ''Take this twice a day.'' What does this mean?"}', '{"text": "Tome esto dos veces al día."}', '["Tome esto dos días.", "Tome dos pastillas.", "Tome esto mañana."]', '{"es": "''Twice a day'' significa dos veces al día. ''Once'' = una vez, ''twice'' = dos veces, ''three times'' = tres veces."}'),
('00000003-0008-0004-0005-000000000001', '00000002-0000-0000-0008-000000000004', 5, 'fill_blank', '{"text": "I''d like to make an ___ with the doctor. (cita)"}', '{"text": "appointment", "accepted": ["appointment"]}', null, '{"es": "''Appointment'' es cita. ''To make an appointment'' = hacer una cita. Es la frase para llamar al médico."}'),
('00000003-0008-0004-0006-000000000001', '00000002-0000-0000-0008-000000000004', 6, 'fill_blank', '{"text": "The ___ will give you a prescription. (médico)"}', '{"text": "doctor", "accepted": ["doctor"]}', null, '{"es": "''Doctor'' es el médico. El médico te da una ''prescription'' (receta médica) para comprar tu medicina."}'),
('00000003-0008-0004-0007-000000000001', '00000002-0000-0000-0008-000000000004', 7, 'translation', '{"text": "Me gustaría hacer una cita con el doctor, por favor."}', '{"text": "I''d like to make an appointment with the doctor, please.", "accepted": ["I''d like to make an appointment with the doctor, please."]}', null, '{"es": "''I''d like to make an appointment'' es la frase para pedir una cita. Siempre añade ''please'' para ser educado."}'),
('00000003-0008-0004-0008-000000000001', '00000002-0000-0000-0008-000000000004', 8, 'translation', '{"text": "Tengo fiebre y me duele la garganta desde hace dos días."}', '{"text": "I have a fever and my throat has been hurting for two days.", "accepted": ["I have a fever and my throat hurts. It has been two days.", "I have had a fever and a sore throat for two days."]}', null, '{"es": "''Sore throat'' es otro término común para garganta adolorida. ''For two days'' indica la duración del problema."}');
